{"entry_id":"24445b2f-6726-4ca5-b579-23665dbefd78","result_id":"2f8dbea6-ec4b-48f3-b7f2-213a371d2620","driver_id":"c09179a4-5655-4f49-ae66-b3c698af8a15","slug":"lucas-gabriel-voieta-parreira","race":2,"laps":[{"number":1,"time_ms":59498,"elapsed_ms":91294}]}
]$payload$::jsonb;
  item jsonb;
  inserted integer;
begin
  -- replay de CI não tem os resultados de produção
  if exists (select 1 from jsonb_array_elements(payload) i
             where not exists (select 1 from public.result_entries e where e.id = (i->>'entry_id')::uuid and e.deleted_at is null)) then
    return;
  end if;

  for item in select * from jsonb_array_elements(payload) loop
    insert into public.laps(result_id, result_entry_id, driver_id, lap_number, lap_time_ms, elapsed_time_ms, valid)
    select (item->>'result_id')::uuid, (item->>'entry_id')::uuid, (item->>'driver_id')::uuid,
           (lap->>'number')::integer, (lap->>'time_ms')::integer, (lap->>'elapsed_ms')::bigint, true
    from jsonb_array_elements(item->'laps') lap
    on conflict (result_entry_id, lap_number) where deleted_at is null do update set
      lap_time_ms = excluded.lap_time_ms, elapsed_time_ms = excluded.elapsed_time_ms, valid = excluded.valid;
  end loop;

  select count(*) into inserted from public.laps l
  where l.result_entry_id in (select (i->>'entry_id')::uuid from jsonb_array_elements(payload) i) and l.deleted_at is null;
  if inserted <> 1199 then raise exception 'Stage 2 laps: esperado 1199, gravado %', inserted; end if;

  update public.sessions s set status = 'homologated', updated_at = now()
  where s.id in (select r.session_id from public.results r
                 where r.id in (select distinct (i->>'result_id')::uuid from jsonb_array_elements(payload) i));
end
$laps$;
